/// <summary>Calculates a nonnegative total; invalid quantities are rejected.</summary>
/// <exception cref="ArgumentOutOfRangeException">An argument is outside its domain.</exception>
static int Total(int unitPrice,int quantity)
{
    if(unitPrice<0) throw new ArgumentOutOfRangeException(nameof(unitPrice));
    if(quantity<=0) throw new ArgumentOutOfRangeException(nameof(quantity));
    return checked(unitPrice*quantity);
}

